{
  "items": [
    {
      "name": "BoxIntegral.Box.mem_univ_Ioc",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {x : ι → ℝ} {I : BoxIntegral.Box ι}, (x ∈ Set.univ.pi fun i => Set.Ioc (I.lower i) (I.upper i)) ↔ x ∈ I"
    },
    {
      "name": "BoxIntegral.Box.mem_def",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (I : BoxIntegral.Box ι) {x : ι → ℝ}, x ∈ I ↔ ∀ (i : ι), x i ∈ Set.Ioc (I.lower i) (I.upper i)"
    },
    {
      "name": "BoxIntegral.Box.mem_mk",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {l u x : ι → ℝ} {H : ∀ (i : ι), l i < u i},\n  x ∈ { lower := l, upper := u, lower_lt_upper := H } ↔ ∀ (i : ι), x i ∈ Set.Ioc (l i) (u i)"
    },
    {
      "name": "BoxIntegral.Box.le_def",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (I J : BoxIntegral.Box ι), I ≤ J ↔ ∀ x ∈ I, x ∈ J"
    },
    {
      "name": "BoxIntegral.Box.instMembershipForallReal",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "instance",
      "type": "{ι : Type u_1} → Membership (ι → ℝ) (BoxIntegral.Box ι)"
    }
  ]
}
